#include <vector>
#include <deque>
#include <algorithm>

class Solution {
public:
    int minimumCoins(std::vector<int>& prices) {
        int n = prices.size();
        std::vector<int> dp(n + 2, 0);
        std::deque<int> q;
        q.push_back(n + 1);
        for (int i = n; i >= 1; --i) {
            while (!q.empty() && q.front() > 2 * i + 1) {
                q.pop_front();
            }
            dp[i] = prices[i - 1] + dp[q.front()];
            while (!q.empty() && dp[q.back()] >= dp[i]) {
                q.pop_back();
            }
            q.push_back(i);
        }
        return dp[1];
    }
};

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public int minimumCoins(int[] prices) {
        int n = prices.length;
        int[] dp = new int[n + 2];
        Deque<Integer> q = new ArrayDeque<>();
        q.addLast(n + 1);
        for (int i = n; i >= 1; i--) {
            while (!q.isEmpty() && q.peekFirst() > 2 * i + 1) {
                q.pollFirst();
            }
            dp[i] = prices[i - 1] + dp[q.peekFirst()];
            while (!q.isEmpty() && dp[q.peekLast()] >= dp[i]) {
                q.pollLast();
            }
            q.addLast(i);
        }
        return dp[1];
    }
}

var minimumCoins = function(prices) {
    const n = prices.length;
    const dp = new Array(n + 2).fill(0);
    const q = [n + 1];
    for (let i = n; i >= 1; i--) {
        while (q.length > 0 && q[0] > 2 * i + 1) {
            q.shift();
        }
        dp[i] = prices[i - 1] + dp[q[0]];
        while (q.length > 0 && dp[q[q.length - 1]] >= dp[i]) {
            q.pop();
        }
        q.push(i);
    }
    return dp[1];
};
